using Microsoft.AspNetCore.Antiforgery;
using Microsoft.AspNetCore.Authentication;
using SalekhPos.Billing.Application.Billing;
using SalekhPos.Billing.Contracts.Billing;
namespace SalekhPos.Api.Authentication; public static class WebBillingEndpoints { public static void MapWebBillingEndpoints(this WebApplication app) { var g = app.MapGroup("/bff/api/v1").AllowAnonymous().RequireRateLimiting("business"); g.MapPost("/organizations/{organizationId:guid}/billing/accounts", Account); g.MapPost("/organizations/{organizationId:guid}/billing/invoices", Invoice); g.MapGet("/organizations/{organizationId:guid}/billing/invoices/{invoiceId:guid}", Get); g.MapPost("/organizations/{organizationId:guid}/billing/invoices/{invoiceId:guid}/charges", Charge); g.MapPost("/organizations/{organizationId:guid}/billing/invoices/{invoiceId:guid}/credits", Credit); } private static async Task<IResult> Account(Guid organizationId, CreateBillingAccountRequest r, HttpContext c, WebAuthenticationState s, IAntiforgery a, IBillingService svc, CancellationToken ct) { var i = await Id(c, s); if (i is null) return Unauth(s); if (!await WebAuthentication.ValidateMutation(c, a, s.Settings!)) return Invalid(); return Results.Ok(await svc.CreateAccountAsync(i, organizationId, r, ct)); } private static async Task<IResult> Invoice(Guid organizationId, CreateInvoiceRequest r, HttpContext c, WebAuthenticationState s, IAntiforgery a, IBillingService svc, CancellationToken ct) { var i = await Id(c, s); if (i is null) return Unauth(s); if (!await WebAuthentication.ValidateMutation(c, a, s.Settings!)) return Invalid(); return Results.Ok(await svc.CreateInvoiceAsync(i, organizationId, r, ct)); } private static async Task<IResult> Get(Guid organizationId, Guid invoiceId, HttpContext c, WebAuthenticationState s, IBillingService svc, CancellationToken ct) { var i = await Id(c, s); return i is null ? Unauth(s) : Results.Ok(await svc.GetInvoiceAsync(i, organizationId, invoiceId, ct)); } private static async Task<IResult> Charge(Guid organizationId, Guid invoiceId, CaptureChargeRequest r, HttpContext c, WebAuthenticationState s, IAntiforgery a, IBillingService svc, CancellationToken ct) { var i = await Id(c, s); if (i is null) return Unauth(s); if (!await WebAuthentication.ValidateMutation(c, a, s.Settings!)) return Invalid(); return Results.Ok(await svc.CaptureChargeAsync(i, organizationId, invoiceId, r, ct)); } private static async Task<IResult> Credit(Guid organizationId, Guid invoiceId, IssueCreditRequest r, HttpContext c, WebAuthenticationState s, IAntiforgery a, IBillingService svc, CancellationToken ct) { var i = await Id(c, s); if (i is null) return Unauth(s); if (!await WebAuthentication.ValidateMutation(c, a, s.Settings!)) return Invalid(); return Results.Ok(await svc.IssueCreditAsync(i, organizationId, invoiceId, r, ct)); } private static async Task<BillingIdentity?> Id(HttpContext c, WebAuthenticationState s) { if (s.Settings is null) return null; var r = await c.AuthenticateAsync(WebAuthentication.CookieScheme); if (!r.Succeeded || r.Principal is null) return null; var iss = r.Principal.FindAll("iss").ToArray(); var sub = r.Principal.FindAll("sub").ToArray(); if (iss.Length != 1 || sub.Length != 1) return null; try { var i = new BillingIdentity(iss[0].Value, sub[0].Value); i.Validate(); return i; } catch (ArgumentException) { return null; } } private static IResult Unauth(WebAuthenticationState s) => s.Settings is null ? Results.Problem(statusCode: 503, title: "Web authentication is unavailable", extensions: new Dictionary<string, object?> { { "code", "web_authentication_unavailable" } }) : Results.Unauthorized(); private static IResult Invalid() => Results.Problem(statusCode: 400, title: "The billing request is invalid", extensions: new Dictionary<string, object?> { { "code", "invalid_billing_request" } }); }
